    faq_title: "Frequently Asked Questions",
    faq_q1: "What are CRM Indicators and how do they work?",
    faq_a1: "CRM Indicators are custom-built TradingView tools designed to simplify market analysis. They provide high-accuracy signals for entries and exits, helping traders follow logic, not luck.",
    faq_q2: "Do I need a TradingView subscription to use your indicators?",
    faq_a2: "Our indicators work on both free and paid TradingView accounts. However, for the best experience and advanced charting features, TradingView subscription is recommended.",
    faq_q3: "How do I use the Free Indicators?",
    faq_a3: "To use our Free Indicators, you need a TradingView account. Simply go to the <strong>Learn More</strong> section of the respective Free Indicator card on our website. At the top, click the <strong>'View on TradingView'</strong> button — the indicator will open in TradingView. From there, click ⭐ <strong>Add to Favorites</strong> and it will appear in your TradingView Indicators 'Favorites' list. <br><br>👉 If you loved our indicators, please follow us on TradingView for more updates!",
    faq_q4: "How do I use the Paid Indicators?",
    faq_a4: "Paid Indicators also require a TradingView account. Unlike Free Indicators, they cannot be directly added. You can start with a <strong>Free Trial</strong> by filling the Google Form linked below the pricing table or in the scrolling banner at the top of our site. <br><br>To continue long-term access, choose a subscription plan from our Pricing Table and complete the payment. After payment, fill out the Google Form (under the pricing table) with your TradingView ID. Our team will then grant you access to the selected indicator(s).",
    faq_q5: "Which markets can I use these indicators on?",
    faq_a5: "You can use them on Equity, Futures, Options, Crypto and Forex — across all timeframes from scalping to swing trading.",
    faq_q6: "What is included in Free Indicators vs Premium Plans?",
    faq_a6: "Free indicators include EMA Cross RSI and EMA Supertrend. Premium plans unlock advanced tools like Ultimate Scalp PRO, MTF Demand Supply, and exclusive CRM combos.",
    faq_q8: "Do you provide refunds?",
    faq_a8: "Since these are digital products, refunds are not provided. We recommend using the Free Trial to test before purchasing.",
    pricing_note: "*Payment terms and prices are subject to change",
