    //aboutus
    title_about: "About Us | Creative Rising Minds",
    about_hero_title: "Built for Traders Who Follow Logic, Not Luck.",
    about_hero_subtitle: "We build the tools we always wished we had.",
    about_story_title: "Our Story",
    about_story_p1: "Creative Rising Minds wasn't born in a boardroom. It was born from countless hours staring at noisy charts, frustrated by lagging indicators and the \"gut-feel\" guesswork that dominates so much of trading. We are traders, just like you, who believe that success in the market should be a result of strategy, discipline, and logic—not luck.",
    about_story_p2: "We were tired of overly complex tools that promised the world but delivered confusion. We wanted clarity. We wanted signals that were reliable, easy to understand, and based on sound market principles. When we couldn't find exactly what we needed, we decided to build it ourselves. That's how CRM began: a mission to create powerful, intuitive, and logical trading indicators for traders who are serious about their craft.",
    about_mission_title: "Our Mission",
    about_mission_p1: "Our mission is simple: <strong>To empower traders with clear, logical, and effective tools that cut through the market noise.</strong> We aim to help you spot the signal, skip the noise, and dominate the trend. We're committed to continuous improvement, community feedback, and providing an arsenal of indicators that help you build confidence and consistency in your trading journey.",
    about_values_title: "Our Core Values",
    about_value_logic_title: "Logic Over Emotion",
    about_value_logic_desc: "Our indicators are built on quantitative rules, not \"gut feelings,\" to help you make systematic decisions.",
    about_value_clarity_title: "Uncompromising Clarity",
    about_value_clarity_desc: "We design our tools to be intuitive and easy to read, eliminating chart clutter so you can focus on what matters.",
    about_value_community_title: "Community Driven",
    about_value_community_desc: "We listen to our users. Your feedback directly shapes our updates and the new tools we build.",
    about_team_title: "Meet the Team",
    about_team1_name: "Riaz Shaikh",
    about_team1_role: "Founder & Lead Developer",
    about_team1_bio: "A passionate trader and programmer, Riaz architects the core CRM indicator logic and leads technical development, transforming complex market concepts into elegant, actionable code.",
    about_team2_name: "Ayaan Shaikh",
    about_team2_role: "Head of Marketing & Digital Content",
    about_team2_bio: "The driving force behind CRM's digital reach, Ayaan creates engaging content, implements SEO strategies, and amplifies our presence across platforms to connect with traders worldwide.",
    about_team3_name: "Arsh Shaikh",
