    footer_note_updated: "છેલ્લું અદ્યતન: જુલાઈ 28, 2025",
    // New Terms and Conditions Page Translations
    tnc_title: "નિયમો અને શરતો | CRM",
    terms_conditions_heading: "નિયમો અને શરતો",
    section_intro: "<strong>ક્રિએટિવ રાઇઝિંગ માઇન્ડ્સ (CRM)</strong> માં આપનું સ્વાગત છે. આ વેબસાઇટનો ઉપયોગ કરીને, તમે નીચેના નિયમો અને શરતોનું પાલન કરવા અને તેના દ્વારા બંધાયેલા રહેવા સંમત થાઓ છો. જો તમે આ શરતોના કોઈપણ ભાગ સાથે અસંમત હો, તો કૃપા કરીને અમારી વેબસાઇટનો ઉપયોગ કરશો નહીં.",
    section_use_content_title: "સામગ્રીનો ઉપયોગ",
    section_use_content: "આ વેબસાઇટ પરની તમામ સામગ્રી, જેમાં ટ્રેડિંગ સૂચકો, ટ્યુટોરિયલ્સ, અને બ્રાન્ડિંગનો સમાવેશ થાય છે, તે CRMની માલિકી છે અને કૉપિરાઇટ કાયદાઓ દ્વારા સુરક્ષિત છે. તમે પૂર્વ લેખિત સંમતિ વિના કોઈપણ સામગ્રીનું પુનઃઉત્પાદન, વિતરણ, અથવા શોષણ કરી શકતા નથી.",
    section_disclaimer_title: "ડિસ્ક્લેમર",
    section_disclaimer: "આ વેબસાઇટ પર પૂરી પાડવામાં આવેલ તમામ ટ્રેડિંગ સૂચકો, સિગ્નલ્સ, અથવા સાધનો માત્ર શૈક્ષણિક અને માહિતીના હેતુઓ માટે છે. અમે નોંધાયેલ નાણાકીય સલાહકારો નથી અને કોઈ રોકાણ સલાહ આપતા નથી. તમે તમારા ટ્રેડિંગ નિર્ણયો માટે સંપૂર્ણપણે જવાબદાર છો.",
    section_payments_subscriptions_title: "ચુકવણી અને સબસ્ક્રિપ્શન્સ",
    section_payments_subscriptions: "અમારા ઉત્પાદનો અથવા સેવાઓ માટે કરવામાં આવેલ તમામ ચુકવણીઓ અંતિમ અને નોન-રિફંડેબલ છે, સિવાય કે અન્યથા જણાવેલ હોય. તમે અમારા પ્લેટફોર્મ પર ખરીદી કરતી વખતે સચોટ અને સંપૂર્ણ ચુકવણી વિગતો પૂરી પાડવા સંમત થાઓ છો.",
    section_limitation_liability_title: "જવાબદારીની મર્યાદા",
    section_limitation_liability: "CRM અમારી વેબસાઇટ અથવા ઉત્પાદનોના ઉપયોગથી ઉદ્ભવતા કોઈપણ સીધા, પરોક્ષ, અથવા પરિણામલક્ષી નુકસાન અથવા હાનિ માટે જવાબદાર રહેશે નહીં. તમે અમારી સેવાઓનો ઉપયોગ તમારા પોતાના જોખમે કરવા સંમત થાઓ છો.",
    section_user_conduct_title: "વપરાશકર્તા આચરણ",
    section_user_conduct: "તમે આ સાઇટનો ઉપયોગ કોઈપણ ગેરકાયદેસર હેતુ માટે અથવા CRM અથવા અન્ય વપરાશકર્તાઓને નુકસાન પહોંચાડે તે રીતે નહીં કરવા સંમત થાઓ છો. આ સાઇટનો દુરુપયોગ તમારા ઍક્સેસની સમાપ્તિમાં પરિણમી શકે છે.",
    section_external_links_title: "બાહ્ય લિંક્સ",
    section_external_links: "અમે તૃતીય-પક્ષ વેબસાઇટ્સની લિંક્સ શામેલ કરી શકીએ છીએ. આ લિંક્સ તમારી સુવિધા માટે પૂરી પાડવામાં આવે છે અને અમારા સમર્થનને સૂચવતા નથી. અમે આ બાહ્ય સાઇટ્સની સામગ્રી અથવા પ્રથાઓ માટે જવાબદાર નથી.",
    section_modifications_title: "સુધારાઓ",
    section_modifications: "અમે આ નિયમો અને શરતોમાં સમયાંતરે સુધારો કરી શકીએ છીએ. નવીનતમ સંસ્કરણ હંમેશા આ પૃષ્ઠ પર પોસ્ટ કરવામાં આવશે. અમારી સાઇટનો સતત ઉપયોગ આ ફેરફારોની સ્વીકૃતિ દર્શાવે છે.",
