    faq_title: "સામાન્યપણે પૂછવામાં આવતા પ્રશ્નો",
    faq_q1: "CRM ઇન્ડિકેટર્સ શું છે અને તેઓ કેવી રીતે કામ કરે છે?",
    faq_a1: "CRM ઇન્ડિકેટર્સ કસ્ટમ-બિલ્ટ ટ્રેડિંગવ્યૂ ટૂલ્સ છે જે માર્કેટ વિશ્લેષણને સરળ બનાવે છે. તેઓ પ્રવેશ અને નીકળવા માટે ઉચ્ચ-સટીકતા સંકેતો આપે છે, જેથી ટ્રેડર્સ તર્કનું પાલન કરે, નહીં કે નસીબનું.",
    faq_q2: "શું મને તમારા ઇન્ડિકેટર્સ ઉપયોગ કરવા માટે ટ્રેડિંગવ્યૂ સબ્સ્ક્રિપ્શનની જરૂર છે?",
    faq_a2: "આપણા ઇન્ડિકેટર્સ ફ્રી અને પેડ ટ્રેડિંગવ્યૂ એકાઉન્ટ્સ પર કામ કરે છે. જો કે, શ્રેષ્ઠ અનુભવ અને એડવાન્સ ચાર્ટિંગ ફીચર્સ માટે ટ્રેડિંગવ્યૂ સબ્સ્ક્રિપ્શનની ભલામણ કરવામાં આવે છે.",
    faq_q3: "હું ફ્રી ઇન્ડિકેટર્સ કેવી રીતે વાપરું?",
    faq_a3: "અમારા ફ્રી ઇન્ડિકેટર્સ વાપરવા માટે ટ્રેડિંગવ્યૂ એકાઉન્ટની જરૂર છે. ફક્ત અમારી વેબસાઇટ પર સંબંધિત ફ્રી ઇન્ડિકેટર કાર્ડના <strong>Learn More</strong> સેક્શનમાં જાઓ. ટોચે <strong>'View on TradingView'</strong> બટન પર ક્લિક કરો — ઇન્ડિકેટર ટ્રેડિંગવ્યૂમાં ખુલશે. ત્યાંથી, ⭐ <strong>Add to Favorites</strong> પર ક્લિક કરો અને તે તમારા ટ્રેડિંગવ્યૂ 'Favorites' ઇન્ડિકેટર્સ યાદીમાં દેખાશે. <br><br>👉 જો તમને અમारा ઇન્ડિકેટર્સ ગમ્યા હોય, તો કૃપા કરીને ટ્રેડિંગવ્યૂ પર અમને ફોલો કરો વધુ અપડેટ્સ માટે!",
    faq_q4: "હું પેડ ઇન્ડિકેટર્સ કેવી રીતે વાપરું?",
    faq_a4: "પેડ ઇન્ડિકેટર્સ માટે પણ ટ્રેડિંગવ્યૂ એકાઉન્ટની જરૂર છે. ફ્રી ઇન્ડિકેટર્સની જેમ તેને ડાયરેક્ટ ઉમેરી શકાતું નથી. તમે પ્રાઇસિંગ ટેબલની નીચેના Google ફોર્મ કે અમારી સાઇટની ટોચે ઉપલબ્ધ સ્ક્રોલિંગ બેનરથી <strong>Free Trial</strong> શરૂ કરી શકો છો. <br><br>દીર્ઘકાલીન ઍક્સેસ માટે, પ્રાઇસિંગ ટેબલમાંથી સબ્સ્ક્રિપ્શન પ્લાન પસંદ કરો અને ચૂકવણી પૂર્ણ કરો. ચૂકવણી પછી, Google ફોર્મ (પ્રાઇસિંગ ટેબલની નીચે) તમારા ટ્રેડિંગવ્યૂ ID સાથે ભરો. અમारी ટીમ પછી પસંદ કરેલ ઇન્ડિકેટર(સ) માટે ઍક્સેસ આપશે.",
    faq_q5: "હું આ ઇન્ડિકેટર્સ કયા બજારોમાં વાપરી શકું?",
    faq_a5: "તમે તેનો ઇક્વિટી, ફ્યુચર્સ, ઓપ્શન્સ, ક્રિપ્ટો અને ફોરેક્સ પર વાપરી શકો છો — સ્કેલ્પિંગથી સ્વિંગ ટ્રેડિંગ સુધીની બધી સમયછેલીમાં.",
    faq_q6: "ફ્રી ઇન્ડિકેટર્સ અને પ્રીમિયમ પ્લાન્સમાં શું સામેલ છે?",
    faq_a6: "ફ્રી ઇન્ડિકેટર્સમાં EMA ક્રોસ RSI અને EMA સુપરટ્રેન્ડ સામેલ છે. પ્રીમિયમ પ્લાન્સમાં અલ્ટિમેટ સ્કેલ્પ પ્રો, MTF ડિમાન્ડ સપ્લાય અને વિશેષ CRM કોમ્બોસ જેવા પ્રગત ટૂલ્સ અનલૉક થાય છે.",
    faq_q8: "શું તમે રિફંડ્સ પૂરા પાડો છો?",
    faq_a8: "આ ડિજિટલ પ્રોડક્ટ્સ હોવાથી રિફંડ્સ આપવામાં આવતા નથી. ખરીદી કરતા પહેલાં ફ્રી ટ્રાયલનો ઉપયોગ કરીને ચકાસવાની ભલામણ કરવામાં આવે છે.",
