    section_intro: "<strong>क्रिएटिव्ह रायझिंग माइंड्स (CRM)</strong> मध्ये आपले स्वागत आहे. या वेबसाइटद्वारे प्रदान केलेली सर्व सामग्री आणि सेवा केवळ <strong>शैक्षणिक आणि माहितीच्या उद्देशाने</strong> आहेत.",
    section_not_financial_advice_title: "आर्थिक सल्ला नाही",
    section_not_financial_advice: "CRM आणि त्यांची टीम हे सेबी-नोंदणीकृत सल्लागार नाहीत. सर्व टूल्स, इंडिकेटर्स आणि शेअर केलेले कंटेंट केवळ शैक्षणिक उद्देशांसाठी आहेत आणि आर्थिक सल्ला मानू नयेत. ट्रेडिंगमध्ये जोखीम आहे — कृपया पात्र सल्लागारांचा सल्ला घ्या. आपल्या गुंतवणुकीच्या निर्णयांसाठी आणि परिणामांसाठी आपण स्वतः जबाबदार आहात.      ",
