    section_use_at_own_risk: "शेअर बाजारात ट्रेडिंगमध्ये जोखीम समाविष्ट आहे. भूतकाळातील कामगिरी भविष्यातील परताव्याची हमी देत नाही. तुम्ही तुमच्या गुंतवणूक निर्णयांसाठी पूर्णपणे जबाबदार आहात आणि CRM किंवा त्याची टीम कोणत्याही नुकसानीसाठी जबाबदार राहणार नाही.",
    section_accuracy_content_title: "अचूकता आणि सामग्री",
    section_accuracy_content: "आम्ही अचूक आणि अद्ययावत माहिती प्रदान करण्याचा प्रयत्न करतो, परंतु आम्ही कोणत्याही सामग्रीच्या अचूकते, पूर्णतेची, किंवा विश्वसनीयतेची कोणतीही हमी देत नाही. त्यावर कृती करण्यापूर्वी नेहमी माहिती स्वतंत्रपणे सत्यापित करा.",
    section_affiliate_content_title: "एफिलिएट आणि प्रचारात्मक सामग्री",
    section_affiliate_content: "आमच्या वेबसाइटवर एफिलिएट लिंक्स किंवा प्रचारात्मक सामग्री असू शकते. तुम्ही या लिंक्स वापरल्यास आम्ही थोडे कमिशन मिळवू शकतो, तुम्हाला कोणताही अतिरिक्त खर्च न करता. तथापि, आम्ही फक्त ती साधने किंवा प्लॅटफॉर्म्सचे प्रचार करतो जे आम्हाला वापरकर्त्यांसाठी मौल्यवान वाटतात.",
