    faq_q3: "मी फ्री इंडिकेटर्स कसे वापरावे?",
    faq_a3: "आमचे फ्री इंडिकेटर्स वापरायासाठी ट्रेडिंगव्ह्यू अकाउंटची गरज आहे. आमच्या वेबसाइटवरील संबंधित फ्री इंडिकेटर कार्डच्या <strong>Learn More</strong> सेक्शनमध्ये जा. वरच्या बाजूस <strong>'View on TradingView'</strong> बटणावर क्लिक करा — इंडिकेटर ट्रेडिंगव्ह्यूमध्ये उघडेल. तिथून, ⭐ <strong>Add to Favorites</strong> वर क्लिक करा आणि तो तुमच्या ट्रेडिंगव्ह्यू इंडिकेटर्स 'Favorites' यादीत दिसेल. <br><br>👉 जर तुम्हाला आमचे इंडिकेटर्स आवडले, तर कृपया ट्रेडिंगव्ह्यूवर आम्हाला फॉलो करा अधिक अपडेटसाठी!",
    faq_q4: "मी पेड इंडिकेटर्स कसे वापरावे?",
    faq_a4: "पेड इंडिकेटर्ससाठी देखील ट्रेडिंगव्ह्यू अकाउंटची गरज आहे. फ्री इंडिकेटर्सप्रमाणे ते थेट जोडले जाऊ शकत नाहीत. तुम्ही प्राइसिंग टेबलखालील Google फॉर्म किंवा आमच्या साइटच्या वरच्या स्क्रोलिंग बॅनरमधून <strong>Free Trial</strong> सुरू करू शकता. <br><br>दीर्घकालीन प्रवेशासाठी, प्राइसिंग टेबलमधून सब्सक्रिप्शन प्लॅन निवडा आणि पेमेंट पूर्ण करा. पेमेंटनंतर, Google फॉर्म (प्राइसिंग टेबलखाली) तुमच्या ट्रेडिंगव्ह्यू IDसह भरा. आमची टीम नंतर निवडलेल्या इंडिकेटर(स) साठी प्रवेश देईल.",
    faq_q5: "मी हे इंडिकेटर्स कोणत्या बाजारांमध्ये वापरू शकतो?",
