    faq_q6: "फ्री इंडिकेटर्स आणि प्रीमियम प्लॅन्समध्ये काय समाविष्ट आहे?",
    faq_a6: "फ्री इंडिकेटर्समध्ये EMA क्रॉस RSI आणि EMA सुपरट्रेंड समाविष्ट आहे. प्रीमियम प्लॅन्समध्ये अल्टीमेट स्कॅल्प प्रो, MTF डिमांड सप्लाय आणि खास CRM कॉम्बोससारखे प्रगत टूल्स अनलॉक होतात.",
