    about_story_p1: "क्रिएटिव्ह रायझिंग माइंड्स ही बोर्डरूममध्ये जन्माला आली नाही. ती असंख्य तास शोरयुक्त चार्ट्सकडे पाहण्यातून, लॅगिंग इंडिकेटर्स आणि \"अंतर्ज्ञान\" अनुमानांमुळे निराश होऊन जन्माला आली. आम्ही तुमच्यासारखेच ट्रेडर्स आहोत, जे मानतात की बाजारातील यश हे रणनीती, शिस्त आणि तर्क यांचा परिणाम असावा—नशिबाचा नाही.",
    about_story_p2: "आम्ही अति जटिल टूल्समधून थकले होते जी जगाचा वादा करतात पण गोंधळ देतात. आम्हाला स्पष्टता हवी होती. आम्हाला विश्वासार्ह, समजण्यास सोपे आणि ठोस बाजार तत्त्वांवर आधारित संकेत हवे होते. जेव्हा आम्हाला अचूक ते मिळाले नाही, तेव्हा आम्ही स्वतः बनवण्याचा निर्णय घेतला. अशाप्रकारे CRM सुरू झाली: गंभीर ट्रेडर्ससाठी शक्तिशाली, सहज आणि तार्किक ट्रेडिंग इंडिकेटर्स बनवण्याचे मिशन.",
    about_mission_title: "आमचे ध्येय",
    about_mission_p1: "आमचे ध्येय सोपे आहे: <strong>ट्रेडर्सना बाजारातील शोर कापून टाकणारी स्पष्ट, तार्किक आणि प्रभावी टूल्स देणे.</strong> आम्ही तुम्हाला संकेत पाहण्यात, शोर सोडण्यात आणि ट्रेंडवर वर्चस्व गाजवण्यात मदत करतो. आम्ही सतत सुधारणा, समुदाय प्रतिक्रिया आणि तुमच्या ट्रेडिंग प्रवासात आत्मविश्वास आणि सातत्य निर्माण करणाऱ्या इंडिकेटर्सच्या शस्त्रागारासाठी वचनबद्ध आहोत.",
    about_values_title: "आमचे मूलभूत मूल्ये",
