    faq_q1: "CRM इंडिकेटर्स क्या हैं और ये कैसे काम करते हैं?",
    faq_a1: "CRM इंडिकेटर्स कस्टम-बिल्ट ट्रेडिंगव्यू टूल्स हैं जो बाजार विश्लेषण को सरल बनाते हैं। ये प्रवेश और निकास के लिए उच्च-सटीकता संकेत प्रदान करते हैं, जिससे ट्रेडर्स तर्क का पालन करें, न कि भाग्य का।",
