    faq_q3: "मैं फ्री इंडिकेटर्स कैसे उपयोग करूं?",
    faq_a3: "हमारे फ्री इंडिकेटर्स का उपयोग करने के लिए ट्रेडिंगव्यू अकाउंट की आवश्यकता है। बस हमारी वेबसाइट पर संबंधित फ्री इंडिकेटर कार्ड के <strong>Learn More</strong> सेक्शन पर जाएं। ऊपर <strong>'View on TradingView'</strong> बटन पर क्लिक करें — इंडिकेटर ट्रेडिंगव्यू में खुलेगा। वहां से, ⭐ <strong>Add to Favorites</strong> पर क्लिक करें और यह आपके ट्रेडिंगव्यू इंडिकेटर्स 'Favorites' सूची में दिखाई देगा। <br><br>👉 अगर आपको हमारे इंडिकेटर्स पसंद आए, तो कृपया ट्रेडिंगव्यू पर हमें फॉलो करें अधिक अपडेट्स के लिए!",
    faq_q4: "मैं पेड इंडिकेटर्स कैसे उपयोग करूं?",
    faq_a4: "पेड इंडिकेटर्स के लिए भी ट्रेडिंगव्यू अकाउंट की आवश्यकता होती है। फ्री इंडिकेटर्स के विपरीत, इन्हें सीधे जोड़ा नहीं जा सकता। आप प्राइसिंग टेबल के नीचे दिए गए Google फॉर्म या हमारी साइट के ऊपरी स्क्रोलिंग बैनर से <strong>Free Trial</strong> शुरू कर सकते हैं। <br><br>दीर्घकालिक एक्सेस के लिए, प्राइसिंग टेबल से सब्सक्रिप्शन प्लान चुनें और भुगतान पूरा करें। भुगतान के बाद, Google फॉर्म (प्राइसिंग टेबल के नीचे) को अपने ट्रेडिंगव्यू ID के साथ भरें। हमारी टीम फिर चुने गए इंडिकेटर(स) के लिए एक्सेस प्रदान करेगी।",
    faq_q5: "इन इंडिकेटर्स का उपयोग मैं किन बाजारों में कर सकता हूँ?",
