function getTranslation(key, fallback) {
  const select = document.getElementById('language-select');
  const lang = select ? select.value : (localStorage.getItem('crm_language') || 'en');
  if (typeof translations !== 'undefined' && translations[lang] && translations[lang][key]) {
    return translations[lang][key];
  }
  return fallback || key;
}

function changeLanguage() {
  const select = document.getElementById('language-select');
  const selectedLang = select.value;
  localStorage.setItem('crm_language', selectedLang);

  document.querySelectorAll('[data-translate]').forEach(element => {
    const key = element.getAttribute('data-translate');
    if (translations[selectedLang][key]) {
      element.innerHTML = translations[selectedLang][key];
    }
  });

  document.documentElement.lang = selectedLang;

  if (typeof renderPricing === 'function') {
    renderPricing();
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const savedLang = localStorage.getItem('crm_language');
  const select = document.getElementById('language-select');
  if (savedLang && select) {
    select.value = savedLang;
  }
  changeLanguage();
});